{
  "roles": [
    "consumer",
    "seller",
    "public body"
  ],
  "if": [
    "the consumer terminates a sales contract as a whole",
    "the consumer terminates a sales contract in accordance with paragraph 2 in relation to some of the goods delivered under the sales contract"
  ],
  "then": "the consumer shall return to the seller, at the seller's expense, the goods; and the seller shall reimburse to the consumer the price paid for the goods upon receipt of the goods or of evidence provided by the consumer of having sent back the goods; and Member States may determine the modalities for return and reimbursement",
  "exceptions": []
}
